/*
 * A082518  Palindromic primes whose digital root equals their middle digits.
 * https://oeis.org/A082518
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 6, u32 n <= 6, u64 n <= 100, u128 n <= 100,
 *            big any n
 * Helpers:   digit_sum, is_prime_big, pow10, rev_decimal
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: palindromic primes with an odd number of digits whose digital
 * root equals the middle digit.
 * The sequence is generated by enumerating odd‑length palindromes in
 * ascending numeric order, checking the digital‑root condition, and
 * testing primality.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stddef.h>

#include "../utils/pow10.h"        /* seq_t pow10(idx_t e) */
#include "../utils/rev_decimal.h"  /* seq_t rev_decimal(seq_t x) */
#include "../utils/digit_sum.h"    /* seq_t digit_sum(seq_t v) */
#include "../utils/is_prime_big.h" /* bool is_prime_big(seq_t n) */

/* Static cache for the sequence.  Each call may receive any n ≥ 1. */
static seq_t *seq = NULL;
static size_t seq_len = 0;   /* number of cached terms */
static size_t seq_cap = 0;   /* capacity of seq */

/* Generation state: k = half‑length of palindrome excluding middle digit.
   gen_fh = current left half, 0 means uninitialised for the current k.
   gen_mid = current middle digit. */
static idx_t    gen_k   = 1;   /* starts with 3‑digit palindromes */
static seq_t    gen_fh  = 0;   /* left half */
static int      gen_mid = 0;   /* middle digit */

/* Grow the cached array if necessary. */
static void grow_seq(void)
{
    if (seq_len == seq_cap) {
        size_t newcap = seq_cap ? seq_cap << 1 : 128;
        seq_t *tmp = (seq_t *)realloc(seq, newcap * sizeof(seq_t));
        seq = tmp;
        seq_cap = newcap;
    }
}

/* Compute the digital root of v (iterated digit sum until a single digit). */
static seq_t digital_root(seq_t v)
{
    seq_t dr = digit_sum(v);
    while (dr >= ((seq_t)10))
        dr = digit_sum(dr);
    return dr;
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    /* The caller guarantees n ≥ 1, but guard against unsound input. */
    if (n < 1)
        return (seq_t)0;

    /* Generate terms until we have at least n of them. */
    while (seq_len < n) {
        /* Initialise left half for a new k when needed. */
        if (gen_fh == (seq_t)0) {
            seq_t start = pow10(gen_k - 1); /* 10^(k-1) */
            gen_fh = start;
        }

        seq_t fh     = gen_fh;
        seq_t rev_fh = rev_decimal(fh);
        seq_t pal    = fh * pow10(gen_k + 1)
                       + (seq_t)gen_mid * pow10(gen_k)
                       + rev_fh;

        /* Check digital‑root condition and primality. */
        if (digital_root(pal) == (seq_t)gen_mid && is_prime_big(pal)) {
            grow_seq();
            seq[seq_len++] = pal;
        }

        /* Advance to the next candidate. */
        ++gen_mid;
        if (gen_mid == 10) {
            gen_mid = 0;
            ++gen_fh;
            seq_t end = pow10(gen_k) - (seq_t)1;
            if (gen_fh > end) {
                ++gen_k;
                gen_fh = (seq_t)0;
            }
        }
    }

    return seq[n - 1];
}
